#include "receiver.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QFile>
#include <QLibrary>
#include <QTimer>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);QTemporaryDir dir;QFile z(QString::fromUtf8(FIXTURE_DIRECTORY)+"/1200-alpha.iqz");if(!z.open(QIODevice::ReadOnly))return 2;QFile file(dir.filePath("fixture.cu8"));if(!file.open(QIODevice::WriteOnly))return 2;file.write(qUncompress(z.readAll()));file.close();QString path=QCoreApplication::applicationDirPath()+"/mock_hackrf.dll";QLibrary lib(path);if(!lib.load())return 2;auto set=reinterpret_cast<void(*)(const char*)>(lib.resolve("mock_fixture"));auto fault=reinterpret_cast<void(*)(int)>(lib.resolve("mock_fault"));auto frequency=reinterpret_cast<unsigned(*)()>(lib.resolve("mock_frequency"));if(!set||!fault||!frequency)return 2;set(file.fileName().toUtf8().constData());qputenv("POCSAG_TEST_HACKRF_LIBRARY",path.toUtf8());auto devices=Receiver::deviceInfos();bool enumerated=false;for(auto d:devices)if(d.key=="hackrf:HACK-SIMULATED"&&d.name.contains("SIMULATED"))enumerated=true;Receiver radio;radio.config.deviceKey="hackrf:HACK-SIMULATED";radio.config.rate=2000000;radio.config.frequency=169626000;radio.config.reconnect=true;int frames=0,tuned=0,errors=0;bool green=false,red=false;QObject::connect(&radio,&Receiver::frame,&app,[&](pocsag::Message m){if(m.text=="REFERENCE 012 FUNCTION TEST"){++frames;if(frames==1){green=radio.hasLiveIq();fault(1);QTimer::singleShot(400,&app,[&]{red=!radio.hasLiveIq();fault(0);});}else if(tuned>=2){radio.stop();app.quit();}}});QObject::connect(&radio,&Receiver::tuned,&app,[&]{++tuned;});QObject::connect(&radio,&Receiver::problem,&app,[&]{++errors;});QTimer::singleShot(18000,&app,[&]{radio.stop();app.quit();});radio.start();app.exec();bool ok=enumerated&&green&&red&&frames>=2&&tuned>=2&&errors>=1&&frequency()==169626000&&!radio.hasLiveIq();std::cout<<"HackRF simulated CS8 reference + reconnect: enum="<<enumerated<<" frames="<<frames<<" tuned="<<tuned<<" errors="<<errors<<" green/red="<<green<<'/'<<red<<" PASS="<<ok<<". No hardware validation.\n";return ok?0:1;}
